<div class="page-actions"><p class="muted">Médicos registrados y su especialidad.</p><?php if(\App\Core\Auth::role()==='admin'):?><a class="btn btn-primary" href="<?= url('/doctors/create') ?>">+ Nuevo médico</a><?php endif;?></div>
<div class="panel"><div class="table-tools"><input class="search-input" data-table-search="#doctorsTable" placeholder="Buscar médico..."></div><div class="table-wrap"><table id="doctorsTable"><thead><tr><th>Médico</th><th>Especialidad</th><th>Colegiado</th><th>Contacto</th><th>Estado</th><th></th></tr></thead><tbody><?php foreach($doctors as $d):?><tr><td><strong><?= e($d['name']) ?></strong></td><td><?= e($d['specialty_name']) ?></td><td><?= e($d['license_no']?:'—') ?></td><td><?= e($d['phone']?:'—') ?><small class="cell-sub"><?= e($d['email']?:'') ?></small></td><td><span class="badge <?= $d['active']?'badge-success':'badge-muted' ?>"><?= $d['active']?'Activo':'Inactivo' ?></span></td><td class="actions"><?php if(\App\Core\Auth::role()==='admin'):?><a class="btn btn-sm" href="<?= url('/doctors/'.$d['id'].'/edit') ?>">Editar</a><form method="post" action="<?= url('/doctors/'.$d['id'].'/delete') ?>" data-confirm="¿Eliminar este médico?"><?= csrf_field() ?><button class="btn btn-sm btn-danger">Eliminar</button></form><?php endif;?></td></tr><?php endforeach;?></tbody></table></div></div>
